            start = 1
            balance = 0
            while start < len(regex):
                if regex[start] == '(':
                    balance += 1
                elif regex[start] == ')':
                    balance -= 1
                if balance == 0:
                    break
                start += 1
            if balance != 0:
                raise ValueError("Unmatched parentheses")

            return ['group'] + parse(regex[1:start]) + parse(regex[start+1:])

        elif regex[0] == '|':
            return ['or'] + parse(regex[1:regex.index(')')]) + parse(regex[regex.index(')')+1:])

        elif regex[0] == '.':
            return ['any_char']

        elif regex[0] == '*':
            if len(regex) == 1:
                raise ValueError("Invalid pattern: '*' requires a preceding character")
            return ['repeat', parse(regex[1])]

        else:
            return ['literal', regex[0]]

    def match_pattern(pattern, text, index=0):
        if index == len(text):
            return pattern == []

        if not pattern:
            return index == len(text)

        if pattern[0] == 'literal':
            if index < len(text) and pattern[1] == text[index]:
                return match_pattern(pattern[1:], text, index + 1)
            else:
                return False

        elif pattern[0] == 'any_char':
            return match_pattern(pattern[1:], text, index + 1)

        elif pattern[0] == 'repeat':
            for i in range(index, len(text) + 1):
                if match_pattern(pattern[1], text, i):
